def parse_args():
    p=argparse.ArgumentParser(description='码单器 AI 可运行全链路测试')
    p.add_argument('html_positional',nargs='?');p.add_argument('--html');p.add_argument('--expected-version');p.add_argument('--report-dir')
    return p.parse_args()

def version_key(path:Path):
    m=re.search(r'码单器\s*(\d+(?:\.\d+)*)',path.stem)
    return tuple(int(x) for x in m.group(1).split('.')) if m else (-1,)

def find_html(explicit):
    if explicit:
        p=Path(explicit).expanduser().resolve()
        if not p.is_file():raise FileNotFoundError(f'目标 HTML 不存在：{p}')
        return p
    candidates=[]
    for root in {Path.cwd(),Path('/mnt/data')}:
        if root.is_dir():candidates.extend(p for p in root.glob('码单器*.html') if p.is_file())
    if not candidates:raise FileNotFoundError('找不到码单器 HTML')
    return max(candidates,key=lambda p:(version_key(p),p.stat().st_mtime_ns)).resolve()

def infer_version(path,html,explicit):
    if explicit:return explicit.strip()
    m=re.search(r"const\s+APP_VERSION\s*=\s*['\"]([^'\"]+)",html)
    return m.group(1) if m else '.'.join(map(str,version_key(path)))

def add(checks,name,ok,detail=''):
    item={'name':name,'ok':bool(ok)}
    if detail:item['detail']=detail
    checks.append(item)

def run_node_payload(html_path,payload,label,extra_env=None):
    if not shutil.which('node'):return {'ok':False,'syntax_ok':False,'error':'未安装 Node.js'}
    with tempfile.TemporaryDirectory() as td:
        js=Path(td)/f'{label}.js';rp=Path(td)/f'{label}.json';js.write_text(payload,encoding='utf-8')
        syntax=subprocess.run(['node','--check',str(js)],capture_output=True,text=True)
        if syntax.returncode:return {'ok':False,'syntax_ok':False,'stderr':syntax.stderr}
        env=os.environ.copy();env.update(extra_env or {})
        env['NODE_PATH']=str(html_path.parent/'node_modules')+(os.pathsep+env['NODE_PATH'] if env.get('NODE_PATH') else '')
        run=subprocess.run(['node',str(js),str(html_path),str(rp)],capture_output=True,text=True,env=env,cwd=str(html_path.parent))
        data=json.loads(rp.read_text(encoding='utf-8')) if rp.exists() else {'ok':False,'error':'missing report'}
        data.update({'syntax_ok':True,'node_returncode':run.returncode,'stdout':run.stdout,'stderr':run.stderr})
        return data

def static_checks(html,version):
    c=[];vp=re.escape(version)
    add(c,f'APP_VERSION 为 {version}',bool(re.search(rf"const\s+APP_VERSION\s*=\s*['\"]{vp}['\"]",html)))
    add(c,f'标题为码单器{version}',bool(re.search(rf'<title>\s*码单器\s*{vp}\s*</title>',html)))
    patterns=[('价格库schema=3',r'PRICE_LIBRARY_SCHEMA_VERSION\s*=\s*3\s*;'),('订单项目schema=2',r'ORDER_PROJECT_SCHEMA_VERSION\s*=\s*2\s*;'),('历史schema=3',r'HISTORY_SCHEMA_VERSION\s*=\s*3\s*;'),('本地schema=5',r'LOCAL_DATA_SCHEMA_VERSION\s*=\s*5\s*;'),('备份schema=4',r'BACKUP_SCHEMA_VERSION\s*=\s*4\s*;')]
    for n,p in patterns:add(c,n,bool(re.search(p,html)))
    add(c,'DOMContentLoaded唯一',html.count('DOMContentLoaded')==1,f"实际{html.count('DOMContentLoaded')}")
    add(c,'AppLifecycle存在','const AppLifecycle' in html);add(c,'Feature Proxy已清零','new Proxy' not in html)
    add(c,'备份完整性校验存在',all(x in html for x in ['fnv1a32','createIntegrity','verifyIntegrity']))
    add(c,'8.2.9主面板背景阴影基线存在',bool(re.search(r'\.input-section\s*,\s*\.result-section\s*\{(?=[^}]*background:\s*var\(--color-bg\))(?=[^}]*box-shadow:\s*var\(--shadow-md\))',html,re.S)))
    for kw in OLD_EXTRACTION_KEYWORDS:add(c,f'旧提取核心已移除：{kw}',kw not in html)
    miss=[x for x in REQUIRED_CLASSES if not re.search(rf'\bclass\s+{re.escape(x)}\b',html)];add(c,f'{len(REQUIRED_CLASSES)}个类完整',not miss,'缺失：'+','.join(miss) if miss else '')
    miss=[x for x in REQUIRED_FEATURES if f"registerFeature('{x}'" not in html];add(c,f'{len(REQUIRED_FEATURES)}个Feature完整',not miss,'缺失：'+','.join(miss) if miss else '')
    miss=[x for x in REQUIRED_STORAGE_KEYS if x not in html];add(c,'核心存储key兼容',not miss,'缺失：'+','.join(miss) if miss else '')
    miss=[x for x in REQUIRED_DOM_IDS if not (re.search(rf'id=["\']{re.escape(x)}["\']',html) or re.search(rf'id:\s*["\']{re.escape(x)}["\']',html))];add(c,'关键DOM ID完整',not miss,'缺失：'+','.join(miss) if miss else '')
    return c

def inline_syntax(html):
    scripts=[]
    for m in re.finditer(r'<script\b([^>]*)>(.*?)</script>',html,re.I|re.S):
        if re.search(r'\bsrc\s*=',m.group(1),re.I):continue
        if m.group(2).strip():scripts.append(m.group(2))
    with tempfile.TemporaryDirectory() as td:
        errors=[]
        for i,s in enumerate(scripts,1):
            p=Path(td)/f'inline_{i}.js';p.write_text(s,encoding='utf-8');r=subprocess.run(['node','--check',str(p)],capture_output=True,text=True)
            if r.returncode:errors.append({'index':i,'stderr':r.stderr.strip()})
        return {'ok':not errors,'script_count':len(scripts),'errors':errors}

