def write_reports(report,html_path,report_dir):
    report_dir.mkdir(parents=True,exist_ok=True);base=html_path.stem;jp=report_dir/f'{base}_AI全链路测试报告.json';tp=report_dir/f'{base}_AI全链路测试摘要.txt';jp.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    lines=[f'{base} AI可运行全链路测试摘要','',f"总结果：{'通过' if report['ok'] else '未通过'}",f'HTML：{html_path}','']
    s=report['static_checks'];lines+=['静态/架构：',f"- {sum(x['ok'] for x in s)}/{len(s)}通过"]
    for x in s:
        if not x['ok']:lines.append(f"  失败：{x['name']}{'｜'+x.get('detail','') if x.get('detail') else ''}")
    syn=report['inline_js_syntax'];lines+=['','JavaScript语法：',f"- {'通过' if syn.get('ok') else '失败'}，内联脚本{syn.get('script_count',0)}个"]
    for key,title in [('engine_report','计算/价格/项目引擎'),('extraction_report','真实提取素材'),('dom_report','完整页面DOM链路')]:
        r=report[key];checks=r.get('checks') or {};lines+=['',title+'：',f"- {sum(1 for x in checks.values() if x.get('ok'))}/{len(checks)}通过"]
        for n,x in checks.items():
            if not x.get('ok'):lines.append(f"  失败：{n}｜{json.dumps(x.get('actual'),ensure_ascii=False)}")
        if r.get('error'):lines.append('  错误：'+r['error'])
    tp.write_text('\n'.join(lines),encoding='utf-8');return jp,tp

def main():
    args=parse_args();html_path=find_html(args.html or args.html_positional);html=html_path.read_text(encoding='utf-8');version=infer_version(html_path,html,args.expected_version);static=static_checks(html,version);syntax=inline_syntax(html);eng=engine_report(html_path);ext=extraction_report(html_path);dom=dom_report(html_path);ok=all(x['ok'] for x in static) and syntax.get('ok') and eng.get('ok') and ext.get('ok') and dom.get('ok');report={'ok':bool(ok),'html':str(html_path),'expected_version':version,'static_checks':static,'inline_js_syntax':syntax,'engine_report':eng,'extraction_report':ext,'dom_report':dom};rd=Path(args.report_dir).expanduser().resolve() if args.report_dir else html_path.parent;jp,tp=write_reports(report,html_path,rd);print(tp.read_text(encoding='utf-8'));print(f'\nJSON报告：{jp}\n文本摘要：{tp}');raise SystemExit(0 if ok else 1)

if __name__=='__main__':main()
